import com.wolinski.shop.money.Money;
import com.wolinski.shop.platform.ShopProblem;

/**
 * Rates are whole basis points (docs/adr/0008): 12.5% is 1250. Text is converted by hand,
 * and a division rounds half up by adding half of the divisor first.
 */
final class BasisPoints {

    static final long ONE_HUNDRED_PERCENT = 10_000;

    private static final long HALF_OF_ONE_HUNDRED_PERCENT = ONE_HUNDRED_PERCENT / 2;

    private BasisPoints() {
    }

    /**
     * Parses a percentage such as "12", "12.5" or "12.50" into basis points.
     * Accepts 0 to 100 inclusive, with at most two decimal places.
     */
    static long parsePercent(String text) {
        String s = null == text ? "" : text.trim();
        int dot = s.indexOf('.');
        String whole = dot < 0 ? s : s.substring(0, dot);
        String fraction = dot < 0 ? "" : s.substring(dot + 1);
        if (whole.isEmpty() && fraction.isEmpty()) {
            throw malformed(text);
        }
        if (fraction.length() > 2) {
            throw new ShopProblem("DISCOUNT_PERCENT_MALFORMED",
                    "percent has more than two decimal places: " + text);
        }

        long wholePercent = 0;
        for (char c : whole.toCharArray()) {
            wholePercent = wholePercent * 10 + digit(c, text);
            if (wholePercent > 100) {
                throw outOfRange(text);
            }
        }

        long bps = wholePercent * 100;
        if (fraction.length() >= 1) {
            bps += digit(fraction.charAt(0), text) * 10;
        }
        if (fraction.length() == 2) {
            bps += digit(fraction.charAt(1), text);
        }
        if (bps > ONE_HUNDRED_PERCENT) {
            throw outOfRange(text);
        }
        return bps;
    }

    /** The discount on {@code total} at {@code bps}, rounded half up to a minor unit. */
    static Money discountOf(Money total, long bps) {
        long minorUnits = total.minorUnits();
        long discount = (minorUnits * bps + HALF_OF_ONE_HUNDRED_PERCENT) / ONE_HUNDRED_PERCENT;
        return new Money(discount, total.currency());
    }

    private static long digit(char c, String text) {
        if (c < '0' || c > '9') {
            throw malformed(text);
        }
        return c - '0';
    }

    private static ShopProblem malformed(String text) {
        return new ShopProblem("DISCOUNT_PERCENT_MALFORMED", "percent is not a number: " + text);
    }

    private static ShopProblem outOfRange(String text) {
        return new ShopProblem("DISCOUNT_PERCENT_OUT_OF_RANGE", "percent must be between 0 and 100: " + text);
    }
}
}

