import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import com.wolinski.shop.money.Money;
import com.wolinski.shop.platform.ShopProblem;
import org.junit.jupiter.api.Test;

class BasisPointsTest {

    @Test
    void parsesPercentTextIntoBasisPoints() {
        assertEquals(1250, BasisPoints.parsePercent("12.5"));
        assertEquals(1250, BasisPoints.parsePercent("12.50"));
        assertEquals(1200, BasisPoints.parsePercent("12"));
        assertEquals(25, BasisPoints.parsePercent(".25"));
        assertEquals(0, BasisPoints.parsePercent("0"));
        assertEquals(10_000, BasisPoints.parsePercent("100"));
        assertEquals(10_000, BasisPoints.parsePercent(" 100.00 "));
    }

    @Test
    void refusesMalformedText() {
        assertCode("DISCOUNT_PERCENT_MALFORMED", "");
        assertCode("DISCOUNT_PERCENT_MALFORMED", ".");
        assertCode("DISCOUNT_PERCENT_MALFORMED", "abc");
        assertCode("DISCOUNT_PERCENT_MALFORMED", "12,5");
        assertCode("DISCOUNT_PERCENT_MALFORMED", "-5");
        assertCode("DISCOUNT_PERCENT_MALFORMED", "+5");
        assertCode("DISCOUNT_PERCENT_MALFORMED", "1e1");
        assertCode("DISCOUNT_PERCENT_MALFORMED", null);
    }

    @Test
    void refusesMoreThanTwoDecimalPlaces() {
        assertCode("DISCOUNT_PERCENT_MALFORMED", "12.505");
    }

    @Test
    void refusesPercentOutsideZeroToOneHundred() {
        assertCode("DISCOUNT_PERCENT_OUT_OF_RANGE", "100.01");
        assertCode("DISCOUNT_PERCENT_OUT_OF_RANGE", "101");
        assertCode("DISCOUNT_PERCENT_OUT_OF_RANGE", "99999999999999999999");
    }

    @Test
    void roundsDiscountHalfUp() {
        // 0.5% of 1.00 PLN is 0.5 minor units, which rounds up to 0.01 PLN.
        assertEquals(Money.pln(1), BasisPoints.discountOf(Money.pln(100), 50));
        // 0.4% of 1.00 PLN is 0.4 minor units, which rounds down to 0.
        assertEquals(Money.pln(0), BasisPoints.discountOf(Money.pln(100), 40));
        // 12.5% of 10.01 PLN is 125.125 minor units, which rounds to 125.
        assertEquals(Money.pln(125), BasisPoints.discountOf(Money.pln(1001), 1250));
        // 12.5% of 10.04 PLN is 125.5 minor units, which rounds up to 126.
        assertEquals(Money.pln(126), BasisPoints.discountOf(Money.pln(1004), 1250));
    }

    private static void assertCode(String code, String text) {
        ShopProblem problem = assertThrows(ShopProblem.class, () -> BasisPoints.parsePercent(text));
        assertEquals(code, problem.code());
    }
}
}

